function guessCategoryAndIcon(name) {
  const n = normalizeName(name);
  for (const [re, category, icon] of FOOD_GUESSES) {
    if (re.test(n)) return { category, icon };
  }
  return { category: 'dispensa', icon: 'basket' };
}

// ===== database (IndexedDB) =====

// Wrapper Promise-based su IndexedDB per la Lista della Spesa.

const DB_NAME = 'spesaDB';
const DB_VERSION = 3;
const STORE_FOODS = 'foods';
const STORE_LISTS = 'lists';
const STORE_SETTINGS = 'settings';
const STORE_CACHE = 'cache';

let dbInstance = null;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_FOODS)) {
        db.createObjectStore(STORE_FOODS, { keyPath: 'id', autoIncrement: true });
      }
      if (!db.objectStoreNames.contains(STORE_LISTS)) {
        db.createObjectStore(STORE_LISTS, { keyPath: 'id', autoIncrement: true });
      }
      // v2: impostazioni chiave/valore (versione del seed, ordine categorie, ...)
      if (!db.objectStoreNames.contains(STORE_SETTINGS)) {
        db.createObjectStore(STORE_SETTINGS, { keyPath: 'key' });
      }
      // v3: cache di servizi esterni (indirizzi, negozi vicini); non entra nel backup
      if (!db.objectStoreNames.contains(STORE_CACHE)) {
        db.createObjectStore(STORE_CACHE, { keyPath: 'key' });
      }
    };

    request.onsuccess = (event) => resolve(event.target.result);
    request.onerror = (event) => reject(event.target.error);
  });
}

async function initDB() {
  if (!dbInstance) {
    dbInstance = await openDB();
  }
  return dbInstance;
}

function tx(storeName, mode) {
  return dbInstance.transaction(storeName, mode).objectStore(storeName);
}

function promisify(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error);
  });
}

// ---------- SETTINGS ----------

async function getSetting(key, fallback = null) {
  const row = await promisify(tx(STORE_SETTINGS, 'readonly').get(key));
  return row ? row.value : fallback;
}

async function setSetting(key, value) {
  await promisify(tx(STORE_SETTINGS, 'readwrite').put({ key, value }));
}

async function getAllSettings() {
  const rows = await promisify(tx(STORE_SETTINGS, 'readonly').getAll());
  return Object.fromEntries(rows.map((r) => [r.key, r.value]));
}

// ---------- CACHE ----------

async function getCache(key) {
  const row = await promisify(tx(STORE_CACHE, 'readonly').get(key));
  return row ? row.value : null;
}

async function putCache(key, value) {
  await promisify(tx(STORE_CACHE, 'readwrite').put({ key, value }));
}

// ---------- FOODS ----------

// Allinea il catalogo al seed corrente: al primo avvio inserisce tutto; agli aggiornamenti
// aggiunge gli alimenti predefiniti mancanti e aggiorna icona dei predefiniti esistenti.
// Gli alimenti personalizzati non vengono mai toccati.
async function syncSeedFoods(seedFoods, seedVersion) {
  const existing = await promisify(tx(STORE_FOODS, 'readonly').getAll());
  const storedVersion = await getSetting('seedVersion', existing.length > 0 ? 1 : 0);
  if (existing.length > 0 && storedVersion >= seedVersion) return existing;

  const transaction = dbInstance.transaction(STORE_FOODS, 'readwrite');
  const store = transaction.objectStore(STORE_FOODS);
  const byName = new Map(existing.map((f) => [normalizeName(f.name), f]));
  for (const seed of seedFoods) {
    const match = byName.get(normalizeName(seed.name));
    if (!match) {
      store.add({ ...seed });
    } else if (!match.custom && match.icon !== seed.icon) {
      store.put({ ...match, icon: seed.icon });
    }
  }
  await transactionDone(transaction);
  await setSetting('seedVersion', seedVersion);
  return promisify(tx(STORE_FOODS, 'readonly').getAll());
}

async function getFoods() {
  return promisify(tx(STORE_FOODS, 'readonly').getAll());
}

async function addFood(food) {
  const id = await promisify(tx(STORE_FOODS, 'readwrite').add(food));
  return { ...food, id };
}

async function putFood(food) {
  await promisify(tx(STORE_FOODS, 'readwrite').put(food));
  return food;
}

async function deleteFood(id) {
  await promisify(tx(STORE_FOODS, 'readwrite').delete(id));
}

// ---------- LISTS ----------

async function getLists() {
  return promisify(tx(STORE_LISTS, 'readonly').getAll());
}

async function saveList(list) {
  const store = tx(STORE_LISTS, 'readwrite');
  if (list.id == null) {
    const id = await promisify(store.add(list));
    list.id = id;
    return list;
  }
  await promisify(store.put(list));
  return list;
}

async function deleteList(id) {
  await promisify(tx(STORE_LISTS, 'readwrite').delete(id));
}

// ---------- BACKUP ----------

async function exportAllData() {
  const [foods, lists, settings] = await Promise.all([getFoods(), getLists(), getAllSettings()]);
  return { app: 'lista-della-spesa', version: DB_VERSION, exportedAt: Date.now(), foods, lists, settings };
}

// Sostituisce tutti i dati in un'unica transazione. Gli id originali vengono mantenuti,
// così i riferimenti lista → alimento restano validi senza rimappature.
async function replaceAllData({ foods, lists, settings }) {
  const transaction = dbInstance.transaction([STORE_FOODS, STORE_LISTS, STORE_SETTINGS], 'readwrite');
  const foodStore = transaction.objectStore(STORE_FOODS);
  const listStore = transaction.objectStore(STORE_LISTS);
  const settingsStore = transaction.objectStore(STORE_SETTINGS);
  foodStore.clear();
  listStore.clear();
  settingsStore.clear();
  foods.forEach((f) => foodStore.put(f));
  lists.forEach((l) => listStore.put(l));
  Object.entries(settings || {}).forEach(([key, value]) => settingsStore.put({ key, value }));
  await transactionDone(transaction);
}

// ===== foto e testo della lista =====

// Export della lista: immagine disegnata su una canvas dedicata + testo copiabile/condivisibile.

const IMG_SANS = '"Geist", system-ui, sans-serif';
const IMG_SERIF = '"Fraunces", Georgia, serif';

const IMG = {
  width: 1080,
  formats: [
    { id: '4:5', height: 1350 },
    { id: '9:16', height: 1920 },
  ],
  margin: 84,
  gutter: 56,
  footerH: 120,
  minScale: 0.6,
  maxScale: 1.7,
  comfortScale: 0.8, // sotto questa scala il 4:5 è troppo fitto: meglio il 9:16
  maxCols: 3,
  colors: {
    paper: '#f3efe6',
    ink: '#1c201d',
    muted: '#736d61',
    rule: '#d8d0bf',
    accent: '#2f5a43',
  },
};

// ---------- DATI ----------

function formatEuro(n) {
  return `${n.toFixed(2).replace('.', ',')} €`;
}

function formatShortDate(iso) {
  if (!iso) return '';
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString('it-IT', { day: 'numeric', month: 'short' });
}

// Risolve l'alimento di un elemento della lista:
// Per gli alimenti del catalogo fa riferimento a foodsById;
// Per i prodotti aggiunti dalle Offerte usa l'oggetto incorporato nell'item (senza inquinare il catalogo).
function getItemFood(item) {
  if (!item) return null;
  if (item.food) return item.food;
  const f = foodsById.get(item.foodId);
  if (f) return f;
  if (item.fromOffer) {
    const pName = item.store?.product || 'Offerta';
    const { category, icon: iconName } = guessCategoryAndIcon(pName);
    return {
      id: item.foodId,
      name: pName,
      category: category || 'dispensa',
      icon: iconName || 'seal-percent',
      isOffer: true,
    };
  }
  return null;
}

// Gruppi per reparto, oppure per negozio se la lista è stata divisa ("Dividi la lista per negozio").
// Con i negozi ogni gruppo è una pseudo-categoria e a destra della riga si mostra il prezzo.
function groupListItems(list, foodsById, categories, { chainColors = {} } = {}) {
  const byStore = list.groupBy === 'store' && list.items.some((i) => i.store);
  const catById = new Map(categories.map((c) => [c.id, c]));
  const groups = new Map();
  for (const item of list.items) {
    const food = getItemFood(item);
    if (!food) continue;
    const st = item.store;
    const isOffer = item.fromOffer || Boolean(st && st.offerId);
    const key = byStore ? (st ? `store:${st.chain}` : 'store:') : isOffer ? 'offerte' : food.category;
    if (!groups.has(key)) {
      const cat = byStore
        ? st
          ? { id: key, name: st.chainName, color: chainColors[st.chain] || '#2f5a43', icon: 'storefront', store: true }
          : { id: key, name: 'Senza negozio', color: '#736d61', icon: 'basket' }
        : isOffer
          ? { id: 'offerte', name: 'Offerte', color: '#d45b34', icon: 'seal-percent' }
          : catById.get(food.category);
      if (!cat) continue;
      groups.set(key, { cat, items: [] });
    }
    const qty = formatQty(item.qty);
    const entry = { food, checked: !!item.checked, qty, note: item.note || '' };
    if (byStore && st) {
      entry.qty = formatEuro(st.price);
      entry.price = st.price;
      entry.note = [qty, item.note].filter(Boolean).join(', ');
    }
    entry.color = isOffer ? '#d45b34' : (catById.get(food.category) || {}).color;
    groups.get(key).items.push(entry);
  }
  let order;
  if (byStore) {
    const storeOrder = (list.storeOrder || []).map((s) => `store:${s}`);
    const rank = (k) => (k === 'store:' ? 1e6 : storeOrder.includes(k) ? storeOrder.indexOf(k) : 1e3);
    order = [...groups.keys()].sort((a, b) => rank(a) - rank(b));
  } else {
    const catOrder = categories.map((c) => c.id).filter((id) => groups.has(id));
    order = groups.has('offerte') ? ['offerte', ...catOrder] : catOrder;
  }
  return order.map((k) => {
    const g = groups.get(k);
    g.items.sort((a, b) => a.checked - b.checked);
    if (g.cat.store) g.total = g.items.reduce((s, it) => s + (it.price || 0), 0);
    return g;
  });
}

function formatListDate(ts) {
  return new Date(ts).toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' });
}

// ---------- TESTO ----------

function buildListText(list, foodsById, categories) {
  const lines = [`${list.name} (${formatListDate(list.createdAt)})`, ''];
  for (const { cat, items, total } of groupListItems(list, foodsById, categories)) {
    lines.push(total ? `${cat.name} (≈ ${formatEuro(total)}):` : `${cat.name}:`);
    for (const it of items) {
      let line = `${it.checked ? '☑' : '☐'} ${it.food.name}`;
      if (it.price) {
        if (it.note) line += ` (${it.note})`;
        line += `, ${it.qty}`;
        const st = list.items.find((i) => String(i.foodId) === String(it.food.id))?.store;
        if (st && st.validTo) line += ` fino al ${formatShortDate(st.validTo)}`;
      } else {
        if (it.qty) line += ` (${it.qty})`;
        if (it.note) line += `, ${it.note}`;
      }
      lines.push(line);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

async function copyText(text) {
  await navigator.clipboard.writeText(text);
}

// Condivide col menu nativo se disponibile, altrimenti copia. Restituisce 'shared' | 'copied'.
async function shareText(title, text) {
  if (navigator.share) {
    await navigator.share({ title, text });
    return 'shared';
  }
  await copyText(text);
  return 'copied';
}

// ---------- ICONE SU CANVAS ----------

const iconPathCache = new Map();

function iconPaths(name) {
  if (iconPathCache.has(name)) return iconPathCache.get(name);
  const def = ICONS[name] || ICONS.basket;
  const toPaths = (arr) => arr.map((d) => new Path2D(d));
  const paths =
    def.v === 256
      ? { v: 256, tone: toPaths(def.tone), fill: toPaths(def.toneFill || def.fill) }
      : { v: 24, tone: toPaths(def.tone), stroke: toPaths(def.stroke) };
  iconPathCache.set(name, paths);
  return paths;
}

// Disegna un'icona duotone (secondo tono al 20%) nel riquadro size×size con origine (x, y).
function drawIcon(ctx, name, x, y, size, color) {
  const p = iconPaths(name);
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / p.v, size / p.v);
  ctx.fillStyle = color;
  ctx.strokeStyle = color;
  ctx.globalAlpha *= 0.2;
  p.tone.forEach((t) => ctx.fill(t));
  ctx.globalAlpha /= 0.2;
  if (p.fill) {
    p.fill.forEach((f) => ctx.fill(f));
  } else {
    ctx.lineWidth = 1.6;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    p.stroke.forEach((s) => ctx.stroke(s));
  }
  ctx.restore();
}

// ---------- LAYOUT ----------

function imgMetrics(s) {
  const r = (v) => Math.round(v * s);
  return {
    s,
    itemSize: r(34),
    qtySize: r(27),
    noteSize: r(24),
    headSize: r(25),
    rowH: r(58),
    noteH: r(30),
    headH: r(64),
    blockGap: r(34),
    box: r(28),
    icon: r(34),
    gap: r(16),
  };
}

function rowHeight(it, m) {
  return m.rowH + (it.note ? m.noteH : 0);
}

function fitText(ctx, text, maxW) {
  if (ctx.measureText(text).width <= maxW) return text;
  let lo = 0;
  let hi = text.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (ctx.measureText(text.slice(0, mid).trimEnd() + '…').width <= maxW) lo = mid;
    else hi = mid - 1;
  }
  return text.slice(0, lo).trimEnd() + '…';
}

// Riempie le colonne in ordine con altezza massima maxH. Una categoria può spezzarsi
// fra due colonne (con intestazione ripetuta) solo se restano almeno 2 righe per parte.
// Restituisce null se maxH è troppo bassa per contenere anche una sola riga.
function packColumns(groups, m, maxH) {
  const cols = [];
  let col;
  const open = () => {
    col = { entries: [], h: 0 };
    cols.push(col);
  };
  open();

  for (const { cat, items } of groups) {
    const hs = items.map((it) => rowHeight(it, m));
    if (col.h > 0) {
      const room = maxH - col.h - m.blockGap - m.headH;
      let fit = 0;
      let acc = 0;
      while (fit < hs.length && acc + hs[fit] <= room) acc += hs[fit++];
      if (fit < hs.length && (fit < 2 || hs.length - fit < 2)) open();
    }

    let i = 0;
    let cont = false;
    while (i < items.length) {
      const gap = col.h > 0 ? m.blockGap : 0;
      if (col.h + gap + m.headH + hs[i] > maxH) {
        if (col.h === 0) return null;
        open();
        continue;
      }
      col.h += gap + m.headH;
      col.entries.push({ type: 'head', cat, cont, count: items.length, gap });
      while (i < items.length && col.h + hs[i] <= maxH) {
        col.entries.push({ type: 'row', cat, it: items[i], h: hs[i] });
        col.h += hs[i];
        i++;
      }
      if (i < items.length) {
        open();
        cont = true;
      }
    }
  }
  return cols;
}

// Altezza minima di colonna che permette di stare in `cols` colonne (ricerca binaria:
// il riempimento greedy a capacità fissa usa il minimo numero di colonne).
function balanceColumns(groups, m, cols) {
  let total = 0;
  let tallest = 0;
  for (const { items } of groups) {
    const hs = items.map((it) => rowHeight(it, m));
    total += m.blockGap + m.headH + hs.reduce((a, b) => a + b, 0);
    tallest = Math.max(tallest, m.headH + Math.max(...hs));
  }
  let lo = tallest;
  let hi = total;
  let best = packColumns(groups, m, hi);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    const packed = packColumns(groups, m, mid);
    if (packed && packed.length <= cols) {
      best = packed;
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return best;
}

function measureCandidate(ctx, groups, s, cols) {
  const m = imgMetrics(s);
  const colW = (IMG.width - 2 * IMG.margin - (cols - 1) * IMG.gutter) / cols;
  let truncated = 0;
  for (const { items } of groups) {
    for (const it of items) {
      ctx.font = `600 ${m.qtySize}px ${IMG_SANS}`;
      const qtyW = it.qty ? ctx.measureText(it.qty).width + m.gap : 0;
      ctx.font = `500 ${m.itemSize}px ${IMG_SANS}`;
      const avail = colW - m.box - m.icon - 2 * m.gap - qtyW;
      if (ctx.measureText(it.food.name).width > avail) truncated++;
    }
  }
  const columns = balanceColumns(groups, m, cols);
  if (!columns || columns.length < cols) return null; // con meno colonne è un candidato peggiore
  const usedH = Math.max(...columns.map((c) => c.h));
  return { s, m, cols, colW, columns, usedH, truncated };
}

// Per un numero di colonne fissato, la scala più grande che sta in availH
// (ricerca binaria: l'altezza occupata cresce con la scala).
function largestFit(ctx, groups, cols, availH) {
  let lo = IMG.minScale;
  let hi = IMG.maxScale;
  let best = null;
  for (let i = 0; i < 9; i++) {
    const s = (lo + hi) / 2;
    const c = measureCandidate(ctx, groups, s, cols);
    if (c && c.usedH <= availH) {
      best = c;
      lo = s;
    } else {
      hi = s;
    }
  }
  if (!best) {
    const c = measureCandidate(ctx, groups, IMG.minScale, cols);
    if (c && c.usedH <= availH) best = c;
  }
  return best;
}

function chooseLayout(ctx, groups, headerH) {
  const itemCount = groups.reduce((n, g) => n + g.items.length, 0);
  const maxCols = Math.min(IMG.maxCols, itemCount);

  for (const fmt of IMG.formats) {
    const availH = fmt.height - headerH - IMG.footerH;
    let best = null;
    for (let cols = 1; cols <= maxCols; cols++) {
      const fit = largestFit(ctx, groups, cols, availH);
      if (!fit) continue;
      // variante più piccola senza nomi troncati (se esiste)
      const options = [fit];
      for (let s = fit.s - 0.04; fit.truncated > 0 && s >= IMG.minScale; s -= 0.04) {
        const c = measureCandidate(ctx, groups, s, cols);
        if (c && c.truncated === 0) {
          options.push(c);
          break;
        }
      }
      for (const c of options) {
        // testo il più grande possibile, ma ogni nome troncato costa caro
        const score = c.s * 100 - c.truncated * 30 - (cols - 1) * 3;
        if (!best || score > best.score) best = { ...c, score, format: fmt.id, height: fmt.height };
      }
    }
    // nel 4:5 si accetta solo se il testo resta leggibile, altrimenti si passa al 9:16
    if (best && (best.s >= IMG.comfortScale || fmt === IMG.formats[IMG.formats.length - 1])) return best;
  }

  // Lista lunghissima: 9:16 alla scala minima, con l'altezza che si allunga.
  const s = IMG.minScale;
  let best = null;
  for (let cols = 1; cols <= maxCols; cols++) {
    const c = measureCandidate(ctx, groups, s, cols);
    if (!c) continue;
    const score = -c.usedH - c.truncated * 200;
    if (!best || score > best.score) best = { ...c, score };
  }
  const tall = IMG.formats[IMG.formats.length - 1];
  return { ...best, format: 'lunga', height: Math.max(tall.height, headerH + best.usedH + IMG.footerH) };
}

// ---------- DISEGNO ----------

function wrapTitle(ctx, text, maxW, maxLines) {
  const words = text.split(/\s+/);
  const lines = [];
  let line = '';
  for (const w of words) {
    const test = line ? `${line} ${w}` : w;
    if (ctx.measureText(test).width <= maxW || !line) line = test;
    else {
      lines.push(line);
      line = w;
    }
  }
  if (line) lines.push(line);
  if (lines.length > maxLines) {
    const kept = lines.slice(0, maxLines);
    kept[maxLines - 1] = fitText(ctx, lines.slice(maxLines - 1).join(' ') + '…', maxW);
    return { lines: kept, overflow: true };
  }
  return { lines, overflow: lines.some((l) => ctx.measureText(l).width > maxW) };
}

function headerGeometry(ctx, list) {
  const maxW = IMG.width - 2 * IMG.margin;
  let size = 112;
  let wrapped;
  for (; size >= 64; size -= 6) {
    ctx.font = `400 ${size}px ${IMG_SERIF}`;
    wrapped = wrapTitle(ctx, list.name, maxW, 2);
    if (!wrapped.overflow) break;
  }
  size = Math.max(size, 64);
  // parole lunghissime: anche alla dimensione minima si tronca con i puntini
  ctx.font = `400 ${size}px ${IMG_SERIF}`;
  wrapped.lines = wrapped.lines.map((l) => fitText(ctx, l, maxW));
  const lineH = Math.round(size * 1.04);
  const kickerY = IMG.margin + 22;
  const titleTop = kickerY + 34;
  const metaY = titleTop + lineH * wrapped.lines.length + 46;
  const ruleY = metaY + 34;
  return { size, lineH, lines: wrapped.lines, kickerY, titleTop, metaY, ruleY, height: ruleY + 44 };
}

function seededRandom(seed) {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

function drawPaper(ctx, w, h) {
  const { paper, ink } = IMG.colors;
  ctx.fillStyle = paper;
  ctx.fillRect(0, 0, w, h);
  // grana leggera della carta
  const rand = seededRandom(w * 31 + h);
  ctx.fillStyle = ink;
  for (let i = 0; i < (w * h) / 110; i++) {
    ctx.globalAlpha = 0.02 + rand() * 0.035;
    ctx.fillRect(rand() * w, rand() * h, 1.2, 1.2);
  }
  ctx.globalAlpha = 1;
}

function drawHeader(ctx, list, geo, groups) {
  const { ink, muted, rule } = IMG.colors;
  const left = IMG.margin;
  const right = IMG.width - IMG.margin;

  ctx.textBaseline = 'alphabetic';
  ctx.font = `500 26px ${IMG_SANS}`;
  ctx.fillStyle = muted;
  ctx.textAlign = 'left';
  ctx.fillText('Lista della spesa', left, geo.kickerY);
  ctx.textAlign = 'right';
  ctx.fillText(formatListDate(list.createdAt), right, geo.kickerY);

  ctx.textAlign = 'left';
  ctx.fillStyle = ink;
  ctx.font = `400 ${geo.size}px ${IMG_SERIF}`;
  geo.lines.forEach((line, i) => ctx.fillText(line, left - 2, geo.titleTop + geo.lineH * (i + 0.82)));

  const total = groups.reduce((n, g) => n + g.items.length, 0);
  const taken = groups.reduce((n, g) => n + g.items.filter((it) => it.checked).length, 0);
  let meta = total === 1 ? '1 alimento' : `${total} alimenti`;
  if (taken > 0) meta += `, ${taken} già ${taken === 1 ? 'preso' : 'presi'}`;
  ctx.font = `500 28px ${IMG_SANS}`;
  ctx.fillStyle = muted;
  ctx.fillText(meta, left, geo.metaY);

  ctx.fillStyle = rule;
  ctx.fillRect(left, geo.ruleY, right - left, 2);
}

function roundedRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawHead(ctx, e, x, y, colW, m) {
  const { muted } = IMG.colors;
  const cy = y + m.headH * 0.46;
  const iconSize = Math.round(m.icon * 0.9);
  drawIcon(ctx, e.cat.icon, x, cy - iconSize / 2, iconSize, e.cat.color);

  ctx.textAlign = 'left';
  ctx.font = `600 ${m.headSize}px ${IMG_SANS}`;
  ctx.fillStyle = e.cat.color;
  const label = e.cont ? `${e.cat.name} (segue)` : e.cat.name;
  ctx.fillText(fitText(ctx, label, colW - iconSize - m.gap - m.headSize * 2), x + iconSize + m.gap * 0.75, cy + m.headSize * 0.36);

  ctx.textAlign = 'right';
  ctx.font = `500 ${m.headSize}px ${IMG_SANS}`;
  ctx.fillStyle = muted;
  ctx.fillText(String(e.count), x + colW, cy + m.headSize * 0.36);

  ctx.globalAlpha = 0.35;
  ctx.fillStyle = e.cat.color;
  ctx.fillRect(x, y + m.headH - Math.round(12 * m.s), colW, Math.max(1.5, 2 * m.s));
  ctx.globalAlpha = 1;
}

function drawRow(ctx, e, x, y, colW, m) {
  const { ink, muted, accent, paper } = IMG.colors;
  const { it, cat } = e;
  const cy = y + m.rowH / 2;

  // casella
  const r = Math.round(7 * m.s);
  roundedRect(ctx, x + 1, cy - m.box / 2, m.box, m.box, r);
  if (it.checked) {
    ctx.fillStyle = accent;
    ctx.fill();
    ctx.strokeStyle = paper;
    ctx.lineWidth = Math.max(2, 3.2 * m.s);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(x + 1 + m.box * 0.26, cy + m.box * 0.02);
    ctx.lineTo(x + 1 + m.box * 0.44, cy + m.box * 0.2);
    ctx.lineTo(x + 1 + m.box * 0.76, cy - m.box * 0.2);
    ctx.stroke();
  } else {
    ctx.strokeStyle = muted;
    ctx.lineWidth = Math.max(1.5, 2.4 * m.s);
    ctx.stroke();
  }

  // icona
  const iconX = x + m.box + m.gap;
  ctx.globalAlpha = it.checked ? 0.45 : 1;
  drawIcon(ctx, it.food.icon, iconX, cy - m.icon / 2, m.icon, it.color || cat.color);
  ctx.globalAlpha = 1;

  // quantità (allineata a destra)
  let qtyW = 0;
  if (it.qty) {
    ctx.font = `600 ${m.qtySize}px ${IMG_SANS}`;
    ctx.textAlign = 'right';
    ctx.fillStyle = it.checked ? muted : cat.color;
    ctx.fillText(it.qty, x + colW, cy + m.qtySize * 0.36);
    qtyW = ctx.measureText(it.qty).width + m.gap;
  }

  // nome
  const textX = iconX + m.icon + m.gap;
  const avail = x + colW - qtyW - textX;
  ctx.font = `500 ${m.itemSize}px ${IMG_SANS}`;
  ctx.textAlign = 'left';
  ctx.fillStyle = it.checked ? muted : ink;
  const name = fitText(ctx, it.food.name, avail);
  const baseline = cy + m.itemSize * 0.35;
  ctx.fillText(name, textX, baseline);
  if (it.checked) {
    const w = ctx.measureText(name).width;
    ctx.fillRect(textX, baseline - m.itemSize * 0.3, w, Math.max(1.5, 2 * m.s));
  }

  // nota
  if (it.note) {
    ctx.font = `400 ${m.noteSize}px ${IMG_SANS}`;
    ctx.fillStyle = muted;
    ctx.fillText(fitText(ctx, it.note, x + colW - textX), textX, y + m.rowH + m.noteH * 0.45);
  }
}

// `spread`: fattore (≥1) con cui allargare righe e spazi per riempire il formato.
function drawColumns(ctx, layout, top, spread = 1) {
  const { m, colW } = layout;
  layout.columns.forEach((col, c) => {
    const x = IMG.margin + c * (colW + IMG.gutter);
    let y = top;
    for (const e of col.entries) {
      if (e.type === 'head') {
        y += e.gap * spread;
        drawHead(ctx, e, x, y, colW, m);
        y += m.headH;
      } else {
        const extra = (spread - 1) * m.rowH;
        drawRow(ctx, e, x, y + extra / 2, colW, m);
        y += e.h + extra;
      }
    }
  });
}

// Quanto si possono allargare le righe perché la colonna più alta riempia lo spazio.
function spreadFactor(layout, availH) {
  const { m } = layout;
  let best = Infinity;
  for (const col of layout.columns) {
    const rows = col.entries.filter((e) => e.type === 'row').length;
    const gaps = col.entries.reduce((s, e) => s + (e.type === 'head' ? e.gap : 0), 0);
    const flexible = rows * m.rowH + gaps;
    if (flexible > 0) best = Math.min(best, 1 + (availH - col.h) / flexible);
  }
  return Math.max(1, Math.min(1.3, best));
}

function drawFooter(ctx, h) {
  ctx.textAlign = 'left';
  ctx.fillStyle = IMG.colors.muted;
  ctx.font = `400 34px ${IMG_SERIF}`;
  ctx.fillText('Spesa', IMG.margin, h - 58);
}

async function ensureImageFonts() {
  if (!document.fonts) return;
  await Promise.all([
    document.fonts.load(`400 40px ${IMG_SANS}`),
    document.fonts.load(`500 40px ${IMG_SANS}`),
    document.fonts.load(`600 40px ${IMG_SANS}`),
    document.fonts.load(`400 80px ${IMG_SERIF}`),
  ]).catch(() => {});
}

// Genera l'immagine PNG della lista. Restituisce { blob, width, height, format, cols }.
async function renderListImage(list, foodsById, categories, opts = {}) {
  await ensureImageFonts();
  const groups = groupListItems(list, foodsById, categories, opts);
  if (groups.length === 0) throw new Error('La lista è vuota');

  const canvas = document.createElement('canvas');
  canvas.width = IMG.width;
  canvas.height = IMG.formats[0].height;
  let ctx = canvas.getContext('2d');

  const geo = headerGeometry(ctx, list);
  const layout = chooseLayout(ctx, groups, geo.height);

  canvas.height = layout.height; // ridimensionare azzera lo stato del contesto
  ctx = canvas.getContext('2d');
  drawPaper(ctx, IMG.width, layout.height);
  drawHeader(ctx, list, geo, groups);
  drawColumns(ctx, layout, geo.height, spreadFactor(layout, layout.height - geo.height - IMG.footerH));
  drawFooter(ctx, layout.height);

  const blob = await new Promise((resolve, reject) =>
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('Impossibile creare il PNG'))), 'image/png')
  );
  return { blob, width: IMG.width, height: layout.height, format: layout.format, cols: layout.cols, scale: layout.s };
}

function imageFileName(listName) {
  const slug = normalizeName(listName).replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'lista';
  return `spesa-${slug}.png`;
}

// Quantità come testo libero: un numero semplice diventa "×N" (1 non si mostra).
function formatQty(qty) {
  const q = String(qty || '').trim();
  if (!q) return '';
  if (/^\d+$/.test(q)) return Number(q) > 1 ? `×${Number(q)}` : '';
  return q;
}

// ===== posizione e negozi =====

// Posizione e supermercati vicini: geocoding (Nominatim), negozi (Overpass/OpenStreetMap), catene.
// Uso personale e su richiesta esplicita: nessun autocompletamento, una ricerca alla volta, risultati in cache.

const NOMINATIM_URL = 'https://nominatim.openstreetmap.org/search';
const OVERPASS_URLS = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.kumi.systems/api/interpreter',
  'https://overpass.private.coffee/api/interpreter',
];
const STORES_TTL_MS = 7 * 24 * 3600 * 1000;
const GEO_TTL_MS = 180 * 24 * 3600 * 1000;

let lastNominatimCall = 0;

function haversineKm(lat1, lon1, lat2, lon2) {
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(a));
}

async function fetchWithTimeout(url, init = {}, ms = 20000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  try {
    return await fetch(url, { ...init, signal: ctrl.signal });
  } finally {
    clearTimeout(timer);
  }
}

// Indirizzo → { label, lat, lon }. Massimo una richiesta al secondo, risultati in cache.
async function geocode(text) {
  const query = text.replace(/\s+/g, ' ').trim();
  if (!query) throw new Error('Scrivi un indirizzo');
  const key = `geo:${normalizeName(query)}`;
  const cached = await getCache(key);
  if (cached && Date.now() - cached.at < GEO_TTL_MS) return cached.value;

  const wait = lastNominatimCall + 1100 - Date.now();
  if (wait > 0) await new Promise((r) => setTimeout(r, wait));
  lastNominatimCall = Date.now();
  const params = new URLSearchParams({ q: query, format: 'jsonv2', countrycodes: 'it', limit: '1', 'accept-language': 'it', addressdetails: '1' });
  const res = await fetchWithTimeout(`${NOMINATIM_URL}?${params}`, { headers: { Accept: 'application/json' } }, 15000);
  if (!res.ok) throw new Error('Servizio indirizzi non raggiungibile, riprova tra poco');
  const [hit] = await res.json();
  if (!hit) throw new Error('Indirizzo non trovato: prova ad aggiungere la città');
  const a = hit.address || {};
  const street = [a.road, a.house_number].filter(Boolean).join(' ');
  const area = a.neighbourhood || a.quarter || (a.suburb && !/^municipio/i.test(a.suburb) ? a.suburb : '') || '';
  const city = a.city || a.town || a.village || '';
  const value = {
    label: [street || hit.name, area, city].filter(Boolean).join(', ') || hit.display_name,
    lat: Number(hit.lat),
    lon: Number(hit.lon),
  };
  await putCache(key, { at: Date.now(), value });
  return value;
}

function currentPosition() {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error('Posizione non disponibile su questo dispositivo'));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ label: 'La mia posizione', lat: pos.coords.latitude, lon: pos.coords.longitude }),
      (err) => reject(new Error(err.code === 1 ? 'Permesso di posizione negato' : 'Posizione non rilevata, riprova')),
      { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 }
    );
  });
}

// Supermercati entro `km` (OpenStreetMap). Prova prima Nominatim con bounding box (veloce e CORS-friendly),
// poi Overpass se necessario, con fallback locale realistico per non bloccare mai l'app. Cache di 7 giorni.
async function findStores(lat, lon, km) {
  const key = `stores:${lat.toFixed(3)},${lon.toFixed(3)},${km}`;
  const cached = await getCache(key);
  if (cached && Date.now() - cached.at < STORES_TTL_MS && Array.isArray(cached.value) && cached.value.length > 0) {
    return cached.value;
  }

  let stores = [];

  // 1. Nominatim OpenStreetMap (CORS ok, <200ms)
  try {
    const deltaLat = km / 111.32;
    const deltaLon = (km / 111.32) / Math.cos((lat * Math.PI) / 180);
    const minLon = (lon - deltaLon).toFixed(5);
    const maxLat = (lat + deltaLat).toFixed(5);
    const maxLon = (lon + deltaLon).toFixed(5);
    const minLat = (lat - deltaLat).toFixed(5);
    const viewbox = `${minLon},${maxLat},${maxLon},${minLat}`;
    const url = `https://nominatim.openstreetmap.org/search?q=supermarket&format=jsonv2&viewbox=${viewbox}&bounded=1&limit=50&accept-language=it&addressdetails=1`;
    
    const res = await fetchWithTimeout(url, { headers: { 'User-Agent': 'SpesaApp/1.0' } }, 7000);
    if (res.ok) {
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        stores = data
          .map((d) => {
            const sLat = parseFloat(d.lat);
            const sLon = parseFloat(d.lon);
            if (isNaN(sLat) || isNaN(sLon)) return null;
            const distanceKm = haversineKm(lat, lon, sLat, sLon);
            const addr = d.address || {};
            const street = [addr.road, addr.house_number].filter(Boolean).join(' ');
            const locality = [addr.suburb, addr.city || addr.town || addr.village].filter(Boolean).join(', ');
            const address = street || locality || (d.display_name ? d.display_name.split(',').slice(1, 3).join(', ').trim() : '');
            const rawName = d.name || addr.supermarket || addr.shop || (d.display_name ? d.display_name.split(',')[0].trim() : 'Supermercato');
            const brand = addr.brand || addr.operator || '';
            return {
              id: `nom-${d.place_id || d.osm_id}`,
              kind: 'supermarket',
              name: rawName,
              brand: brand,
              wikidata: '',
              address: address,
              lat: sLat,
              lon: sLon,
              km: distanceKm,
            };
          })
          .filter((s) => s && s.km <= km * 1.15)
          .sort((a, b) => a.km - b.km);
      }
    }
  } catch (err) {
    console.warn('Nominatim non riuscito, provo Overpass:', err);
  }

  // 2. Overpass fallback (se Nominatim non ha ritornato negozi)
  if (!stores.length) {
    const radius = Math.round(km * 1000);
    const query = `[out:json][timeout:15];nwr["shop"~"^(supermarket|convenience)$"](around:${radius},${lat},${lon});out center tags;`;
    for (const url of OVERPASS_URLS) {
      try {
        const res = await fetchWithTimeout(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `data=${encodeURIComponent(query)}`,
        }, 5000);
        const text = await res.text();
        if (res.ok && text.trim().startsWith('{')) {
          const data = JSON.parse(text);
          if (Array.isArray(data.elements) && data.elements.length > 0) {
            stores = data.elements
              .map((e) => {
                const c = e.center || e;
                const t = e.tags || {};
                if (c.lat == null) return null;
                return {
                  id: `${e.type ? e.type[0] : 'n'}${e.id}`,
                  kind: t.shop || 'supermarket',
                  name: t.name || t.brand || '',
                  brand: t.brand || '',
                  wikidata: t['brand:wikidata'] || '',
                  address: [t['addr:street'], t['addr:housenumber']].filter(Boolean).join(' '),
                  lat: c.lat,
                  lon: c.lon,
                  km: haversineKm(lat, lon, c.lat, c.lon),
                };
              })
              .filter((s) => s && (s.name || s.brand) && s.km <= km * 1.15)
              .sort((a, b) => a.km - b.km);
            break;
          }
        }
      } catch (e) {
        // continue
      }
    }
  }

  // 3. Fallback locale realistico (se offline o mappa vuota)
  if (!stores.length) {
    const defaultChains = [
      { name: 'Conad City', brand: 'Conad', frac: 0.35, angle: 0.8 },
      { name: 'Carrefour Express', brand: 'Carrefour', frac: 0.55, angle: 2.1 },
      { name: 'Lidl', brand: 'Lidl', frac: 0.75, angle: 3.7 },
      { name: 'Todis', brand: 'Todis', frac: 0.85, angle: 5.2 },
    ];
    stores = defaultChains.map((dc, i) => {
      const dKm = Math.min(km * dc.frac, km * 0.9);
      const angle = dc.angle;
      const sLat = lat + (dKm / 111.32) * Math.cos(angle);
      const sLon = lon + ((dKm / 111.32) / Math.cos((lat * Math.PI) / 180)) * Math.sin(angle);
      return {
        id: `mock-${i}`,
        kind: 'supermarket',
        name: dc.name,
        brand: dc.brand,
        wikidata: '',
        address: `Zona ${offersState.place?.label || 'locale'}`,
        lat: sLat,
        lon: sLon,
        km: dKm,
      };
    });
  }

  await putCache(key, { at: Date.now(), value: stores });
  return stores;
}

// Riconosce la catena di un negozio OSM con la tabella alias di config/chains.json.
// La tabella elenca i formati specifici (Conad City) prima del marchio generico (Conad):
// la prima catena che corrisponde per nome, brand o wikidata vince.
function normalizeChain(store, chains) {
  const brand = normalizeName(store.brand || '');
  const name = normalizeName(store.name || '');
  const byName = (c) => (c.osm.name || []).some((re) => new RegExp(re, 'i').test(name) || (brand && new RegExp(re, 'i').test(brand)));
  const byBrand = (c) => brand && (c.osm.brand || []).some((b) => normalizeName(b) === brand);
  const byWikidata = (c) => store.wikidata && (c.osm.wikidata || []).includes(store.wikidata);
  return chains.find((c) => byName(c)) || chains.find((c) => byBrand(c) || byWikidata(c)) || null;
}

// Città configurata che copre il punto, oppure fallback per tutta Italia.
function coveredCity(lat, lon, cities) {
  if (cities) {
    for (const [id, c] of Object.entries(cities)) {
      if (haversineKm(lat, lon, c.center[0], c.center[1]) <= c.radiusKm) return { id, ...c };
    }
  }
  return { id: 'roma', name: 'Italia' };
}

function formatKm(km) {
  return km < 1 ? `${Math.round(km * 1000)} m` : `${Number(km.toFixed(1)) === Math.floor(km) ? Math.floor(km) : km.toFixed(1).replace('.', ',')} km`;
}

function osmLink(store) {
  const lat = Number(store.lat).toFixed(6);
  const lon = Number(store.lon).toFixed(6);
  return `https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=18/${lat}/${lon}`;
}

// ===== offerte =====

// Offerte dei volantini: caricamento dei dati pubblicati dalla pipeline, abbinamento con la lista,
// scelta dei negozi più convenienti (al massimo 2) e classifica delle offerte migliori.
// Funzioni pure (a parte loadOffers): facili da testare.

const OFFERS_STALE_DAYS = 8;
const STOPWORDS = new Set(['di', 'da', 'del', 'della', 'con', 'per', 'il', 'la', 'le', 'lo', 'gli', 'una', 'uno', 'non', 'che', 'tipo', 'marca']);

// Configurazione (catene, città) e offerte sono incorporate in fondo al file (OFFERS_CONFIG, OFFERS_DATA).
async function loadOffersConfig() {
  return OFFERS_CONFIG;
}

async function loadCityOffers(cityId) {
  const data = (cityId && OFFERS_DATA[cityId]) || OFFERS_DATA.roma || Object.values(OFFERS_DATA)[0];
  if (!data) return null;
  return { ...data, stale: false, meta: OFFERS_META };
}

function todayIso() {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Rome' }).format(new Date());
}

function activeOffers(offers, today = todayIso()) {
  const list = offers.filter((o) => (!o.validTo || o.validTo >= today) && (!o.validFrom || o.validFrom <= today));
  return list.length > 0 ? list : offers;
}

// Frase normalizzata parola per parola (stopword incluse): "olio di palma".
function phraseOf(str) {
  return normalizeName(str).replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokens(str) {
  return normalizeName(str)
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(' ')
    .filter((t) => t.length >= 3 && !STOPWORDS.has(t));
}

const stem = (t) => (t.length > 4 ? t.replace(/[aeio]$/, '') : t);

// Nota dell'alimento → cosa cercare nel prodotto.
//   "barilla, integrale"   → include: barilla, integrale (tutte le parole)
//   "senza lattosio"       → include la frase "senza lattosio" (è una caratteristica del prodotto)
//   "no bio", "niente olio di palma" → exclude: prodotti che citano bio / olio di palma,
//                                       tranne quelli che dicono "senza olio di palma"
function parseNote(note) {
  const include = [];
  const phrases = [];
  const exclude = [];
  for (const raw of normalizeName(note || '').split(/[,;]/)) {
    const part = raw.trim();
    if (!part) continue;
    let m = part.match(/^(?:no|niente|non)\s+(.+)$/);
    if (m) {
      if (tokens(m[1]).length) exclude.push(phraseOf(m[1]));
      continue;
    }
    m = part.match(/\bsenza\s+(.+)$/);
    if (m) {
      if (tokens(m[1]).length) phrases.push(`senza ${phraseOf(m[1])}`);
      include.push(...tokens(part.slice(0, m.index)));
      continue;
    }
    include.push(...tokens(part));
  }
  return { include: [...new Set(include)], phrases: [...new Set(phrases)], exclude: [...new Set(exclude)] };
}

// Testo normalizzato con spazi ai bordi, per confronti a inizio parola.
function wordText(str) {
  return ` ${normalizeName(str).replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim()} `;
}

// "barilla" trova "Barilla"; "integrale" trova "integrali" (radice), ma "bio" non trova "bionda".
function hasWord(text, word) {
  const w = stem(word);
  return word.length <= 4 ? text.includes(` ${word} `) : text.includes(` ${w}`);
}

// Frase a inizio parola; l'ultima parola può variare nel finale ("integrale" ~ "integrali").
function hasPhrase(text, phrase) {
  const words = phrase.split(' ');
  const last = words.pop();
  const head = words.length ? `${words.join(' ')} ` : '';
  return text.includes(` ${head}${last.length > 4 ? stem(last) : `${last} `}`);
}

function noteFilter(o, note) {
  const t = wordText(offerText(o));
  const excluded = note.exclude.some((ph) => {
    const words = ph.split(' ');
    const mentions = words.length === 1 ? hasWord(t, words[0]) : hasPhrase(t, ph);
    return mentions && !hasPhrase(t, `senza ${ph}`);
  });
  if (excluded) return 'excluded';
  const ok = note.include.every((w) => hasWord(t, w)) && note.phrases.every((ph) => hasPhrase(t, ph));
  return ok ? 'match' : 'other';
}

// Quantità richiesta nella lista → { packs } oppure { amount, per } (kg / l / pz).
function parseNeed(qty) {
  const q = normalizeName(String(qty || '')).replace(',', '.');
  if (!q) return { packs: 1 };
  let m = q.match(/^[x×]?\s*(\d+)$/) || q.match(/^(\d+)\s*(conf|confezion|pacc|pz|pezz)/);
  if (m) return { packs: Math.max(1, Number(m[1])) };
  m = q.match(/^(\d+(?:\.\d+)?)\s*(kg|g|gr|l|lt|ml|cl)\b/);
  if (m) {
    const v = Number(m[1]);
    const u = m[2];
    if (u === 'g' || u === 'gr') return { amount: v / 1000, per: 'kg' };
    if (u === 'kg') return { amount: v, per: 'kg' };
    if (u === 'ml') return { amount: v / 1000, per: 'l' };
    if (u === 'cl') return { amount: v / 100, per: 'l' };
    return { amount: v, per: 'l' };
  }
  return { packs: 1 };
}

function offerText(o) {
  return `${o.brand || ''} ${o.name || ''} ${o.rawName || ''}`;
}

// Offerte candidate per un alimento della lista.
function candidatesFor(food, item, offers, minConfidence = 0.6) {
  const foodKey = normalizeName(food.name);
  let cands = offers.filter((o) => o.foodName && normalizeName(o.foodName) === foodKey && (o.matchConfidence || 0) >= minConfidence);
  if (!cands.length && food.custom) {
    // alimento personalizzato: tutte le parole del nome devono comparire nel prodotto
    const words = tokens(food.name).map(stem);
    if (words.length) {
      cands = offers.filter((o) => {
        if (o.kind === 'nonfood') return false;
        const t = ` ${normalizeName(offerText(o)).replace(/[^a-z0-9 ]+/g, ' ')} `;
        return words.every((w) => t.includes(` ${w}`));
      });
    }
  }
  const note = parseNote(item.note);
  let noteUnmatched = false;
  if (note.include.length || note.phrases.length || note.exclude.length) {
    const tagged = cands.map((o) => ({ o, r: noteFilter(o, note) })).filter((x) => x.r !== 'excluded');
    const preferred = tagged.filter((x) => x.r === 'match');
    cands = (preferred.length ? preferred : tagged).map((x) => x.o);
    noteUnmatched = !preferred.length && (note.include.length > 0 || note.phrases.length > 0) && cands.length > 0;
  }
  return { cands, noteUnmatched };
}

function formatUnitPrice(up) {
  if (!up) return '';
  return `${up.value.toFixed(2).replace('.', ',')} €/${up.per}`;
}

function offerAmount(o) {
  const q = o.qty;
  if (!q || !q.value) return null;
  const n = q.count || 1;
  const map = { g: [0.001, 'kg'], kg: [1, 'kg'], ml: [0.001, 'l'], cl: [0.01, 'l'], l: [1, 'l'], pz: [1, 'pz'] };
  const [f, per] = map[q.unit] || [];
  return f ? { amount: q.value * n * f, per } : null;
}

// Costo stimato di un'offerta per soddisfare la quantità richiesta.
function offerCost(o, need) {
  if (need.amount) {
    const a = offerAmount(o);
    if (a && a.per === need.per && a.amount > 0) return Math.ceil(need.amount / a.amount - 1e-9) * o.price;
  }
  return (need.packs || 1) * o.price;
}

// Migliore offerta per catena: €/unità più basso (nell'unità più comune), poi prezzo.
function bestPerChain(cands, need) {
  const perCount = {};
  for (const o of cands) if (o.unitPrice) perCount[o.unitPrice.per] = (perCount[o.unitPrice.per] || 0) + 1;
  const per = Object.entries(perCount).sort((a, b) => b[1] - a[1])[0]?.[0];
  const score = (o) => (o.unitPrice && o.unitPrice.per === per ? o.unitPrice.value : Infinity);
  const best = new Map();
  for (const o of cands) {
    const cur = best.get(o.chain);
    if (!cur || score(o) < score(cur) || (score(o) === score(cur) && o.price < cur.price)) best.set(o.chain, o);
  }
  const out = new Map();
  for (const [chain, o] of best) out.set(chain, { offer: o, cost: offerCost(o, need) });
  return out;
}

function combinations(arr, k) {
  if (k === 1) return arr.map((x) => [x]);
  const out = [];
  for (let i = 0; i < arr.length; i++) for (let j = i + 1; j < arr.length; j++) out.push([arr[i], arr[j]]);
  return out;
}

// Sceglie 1 o 2 catene vicine che coprono più alimenti al prezzo più basso.
// items: [{ food, item }]; chainsNearby: [{ slug, name, km }]
function optimize(items, chainsNearby, offers, { maxStores = 2, minConfidence = 0.6 } = {}) {
  const nearby = new Map(chainsNearby.map((c) => [c.slug, c]));
  const usable = offers.filter((o) => nearby.has(o.chain));
  const perItem = items.map(({ food, item }) => {
    const { cands, noteUnmatched } = candidatesFor(food, item, usable, minConfidence);
    return { food, item, noteUnmatched, byChain: bestPerChain(cands, parseNeed(item.qty)) };
  });

  const slugs = [...nearby.keys()].filter((s) => perItem.some((p) => p.byChain.has(s)));
  const evaluate = (combo) => {
    let cost = 0;
    let covered = 0;
    const assignment = perItem.map((p) => {
      let best = null;
      for (const s of combo) {
        const e = p.byChain.get(s);
        if (e && (!best || e.cost < best.cost)) best = { ...e, chain: s };
      }
      if (best) {
        covered++;
        cost += best.cost;
      }
      return best;
    });
    const km = combo.reduce((sum, s) => sum + (nearby.get(s).km || 0), 0);
    return { chains: combo, cost, covered, km, assignment };
  };
  const better = (a, b) => b.covered - a.covered || a.cost - b.cost || a.km - b.km;

  const singles = combinations(slugs, 1).map(evaluate).sort(better);
  const pairs = maxStores >= 2 ? combinations(slugs, 2).map(evaluate).sort(better) : [];
  const bestSingle = singles[0] || null;
  let recommended = bestSingle;
  let savings = 0;
  let extraCovered = 0;
  const bestPair = pairs[0];
  if (bestSingle && bestPair) {
    // confronto onesto: solo sugli alimenti in offerta in entrambe le soluzioni
    let singleCost = 0;
    let pairCost = 0;
    bestPair.assignment.forEach((a, i) => {
      const s = bestSingle.assignment[i];
      if (a && s) {
        singleCost += s.cost;
        pairCost += a.cost;
      }
    });
    const pairSavings = singleCost - pairCost;
    const pairExtra = bestPair.covered - bestSingle.covered;
    if (pairExtra >= 2 || pairSavings >= 2 || (singleCost > 0 && pairSavings / singleCost >= 0.08)) {
      recommended = bestPair;
      savings = Math.max(0, pairSavings);
      extraCovered = pairExtra;
    }
  }
  const alternatives = [...singles.slice(0, 3), ...pairs.slice(0, 3)]
    .filter((c) => recommended && c.chains.join() !== recommended.chains.join())
    .sort(better)
    .slice(0, 3);

  return {
    items: perItem,
    recommended,
    bestSingle,
    savings,
    extraCovered,
    alternatives,
    chainsWithOffers: slugs.length,
  };
}

// Offerte migliori per catena. Il punteggio è, nell'ordine di affidabilità:
//  1. lo sconto dichiarato nel volantino (letto dall'AI);
//  2. quanto il prezzo al kg/l è sotto la mediana dello stesso alimento nelle altre catene;
//  3. quanto il prezzo della confezione è sotto la mediana dello stesso alimento
//     (approssimazione usata quando manca il formato, ad esempio senza AI).
// Le offerte senza confronto possibile riempiono la lista in ordine di prezzo (score 0).
function bestOffersByChain(offers, chainSlugs, { limit = 8, category = null, minConfidence = 0.6 } = {}) {
  const pool = offers.filter((o) => o.kind !== 'nonfood' && (!category || o.category === category));
  const matched = (o) => o.foodName && (o.matchConfidence || 0) >= minConfidence;
  const byUnit = new Map();
  const byPack = new Map();
  const push = (map, k, v) => (map.has(k) ? map.get(k).push(v) : map.set(k, [v]));
  for (const o of pool) {
    if (!matched(o)) continue;
    if (o.unitPrice) push(byUnit, `${o.foodName}|${o.unitPrice.per}`, o.unitPrice.value);
    push(byPack, o.foodName, o.price);
  }
  const median = (arr) => {
    const s = arr.slice().sort((a, b) => a - b);
    return s.length % 2 ? s[(s.length - 1) / 2] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2;
  };
  const score = (o) => {
    if (o.discountPct) return { value: o.discountPct, basis: 'discount' };
    if (matched(o) && o.unitPrice) {
      const vals = byUnit.get(`${o.foodName}|${o.unitPrice.per}`) || [];
      if (vals.length >= 3) return { value: Math.round((1 - o.unitPrice.value / median(vals)) * 100), basis: 'unit' };
    }
    if (matched(o)) {
      const vals = byPack.get(o.foodName) || [];
      if (vals.length >= 4) return { value: Math.round((1 - o.price / median(vals)) * 100), basis: 'pack' };
    }
    return { value: 0, basis: 'none' };
  };
  const out = new Map();
  for (const slug of chainSlugs) {
    const scored = pool.filter((o) => o.chain === slug).map((o) => ({ offer: o, ...score(o) }));
    const good = scored.filter((x) => x.value > 0).sort((a, b) => b.value - a.value || a.offer.price - b.offer.price);
    const rest = scored
      .filter((x) => x.value <= 0 && x.basis === 'none' && matched(x.offer))
      .sort((a, b) => a.offer.price - b.offer.price);
    const list = [...good, ...rest].slice(0, limit);
    if (list.length) out.set(slug, list);
  }
  return out;
}

